package com.bosshittracker;

/**
 * A boss you are currently fighting, before it dies.
 */
class ActiveFight
{
	final String boss;
	final KillRecord record;
	/** Set when the NPC dies; the kill is saved when it despawns. */
	boolean died;

	// Hits you saw from other players, and how much of that party members reported.
	// The difference is damage from players who weren't sharing.
	int othersSeenHits;
	long othersSeenDamage;
	int partyReportedHits;
	long partyReportedDamage;

	ActiveFight(String boss, long startTime)
	{
		this(boss, new KillRecord(startTime));
	}

	ActiveFight(String boss, KillRecord record)
	{
		this.boss = boss;
		this.record = record;
	}
}

package com.bosshittracker;

import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * One hit a party member landed on a tracked NPC, shared with the rest of the party.
 */
public class BossHitPartyHit extends PartyMemberMessage
{
	private String boss;
	private int npcIndex;
	private String weapon;
	private int amount;

	/** Used by Gson when the message arrives. */
	@SuppressWarnings("unused")
	public BossHitPartyHit()
	{
	}

	public BossHitPartyHit(String boss, int npcIndex, String weapon, int amount)
	{
		this.boss = boss;
		this.npcIndex = npcIndex;
		this.weapon = weapon;
		this.amount = amount;
	}

	public String getBoss()
	{
		return boss;
	}

	public int getNpcIndex()
	{
		return npcIndex;
	}

	public String getWeapon()
	{
		return weapon;
	}

	public int getAmount()
	{
		return amount;
	}
}

package com.bosshittracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(BossHitTrackerConfig.GROUP)
public interface BossHitTrackerConfig extends Config
{
	String GROUP = "bosshittracker";

	@ConfigItem(
		keyName = "bossesOnly",
		name = "Bosses only",
		description = "Only track hits on bosses. Turn off to track hits on every NPC you kill.",
		position = 0
	)
	default boolean bossesOnly()
	{
		return true;
	}

	@ConfigItem(
		keyName = "extraNpcs",
		name = "Extra NPCs to track",
		description = "Comma-separated NPC names to track in addition to the built-in boss list (e.g. Tormented Demon, Wyrm)",
		position = 1
	)
	default String extraNpcs()
	{
		return "";
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "Show fight overlay",
		description = "Show your hits for the current fight in an on-screen overlay",
		position = 2
	)
	default boolean showOverlay()
	{
		return true;
	}

	@ConfigItem(
		keyName = "trackSpells",
		name = "Track spells",
		description = "Track magic hits per spell, e.g. \"Kodai wand (Ice Barrage)\", for both manual casts and autocast",
		position = 3
	)
	default boolean trackSpells()
	{
		return true;
	}

	@ConfigItem(
		keyName = "partyBreakdown",
		name = "Party breakdown",
		description = "When you're in a RuneLite Party, share your hits with the party and record each player's hits per weapon for every kill. Party members need Boss Hit Tracker installed; anyone else is listed as \"Other players\".",
		position = 4
	)
	default boolean partyBreakdown()
	{
		return true;
	}

	@Range(min = 1, max = 200)
	@ConfigItem(
		keyName = "historySize",
		name = "Kills kept per boss",
		description = "How many individual kills to keep in each boss's kill history",
		position = 5
	)
	default int historySize()
	{
		return 50;
	}
}

package com.bosshittracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Shows your hits on the boss you're currently fighting.
 */
class BossHitTrackerOverlay extends OverlayPanel
{
	private final BossHitTrackerPlugin plugin;
	private final BossHitTrackerConfig config;

	@Inject
	BossHitTrackerOverlay(BossHitTrackerPlugin plugin, BossHitTrackerConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}
		ActiveFight fight = plugin.getCurrentFightSnapshot();
		if (fight == null)
		{
			return null;
		}

		long seconds = (System.currentTimeMillis() - fight.record.getTimestamp()) / 1000;
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(fight.boss)
			.color(Color.ORANGE)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("Time")
			.right(String.format("%d:%02d", seconds / 60, seconds % 60))
			.build());

		for (Map.Entry<String, WeaponStats> e : fight.record.getWeapons().entrySet())
		{
			WeaponStats w = e.getValue();
			panelComponent.getChildren().add(LineComponent.builder()
				.left(e.getKey())
				.leftColor(Color.LIGHT_GRAY)
				.right(w.getHits() + " hits / " + w.getDamage())
				.build());
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left("Total")
			.right(fight.record.getTotalHits() + " hits / " + fight.record.getTotalDamage())
			.rightColor(Color.GREEN)
			.build());

		// Party members' damage this fight
		if (fight.record.hasOtherPlayers())
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text("Party")
				.color(Color.ORANGE)
				.build());
			for (Map.Entry<String, Map<String, WeaponStats>> e : fight.record.getPlayers().entrySet())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(e.getKey())
					.leftColor(Color.LIGHT_GRAY)
					.right(String.valueOf(KillRecord.totalDamage(e.getValue())))
					.build());
			}
		}

		panelComponent.setPreferredSize(new Dimension(190, 0));
		return super.render(graphics);
	}
}

package com.bosshittracker;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.text.NumberFormat;
import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel: pick a boss, then pick one kill (or all kills) to see your hits per weapon.
 */
class BossHitTrackerPanel extends PluginPanel
{
	private static final NumberFormat NUMBER = NumberFormat.getIntegerInstance();
	private static final String ALL_KILLS = "All kills (lifetime)";
	/** Kill selection meaning "lifetime totals" rather than one kill. */
	private static final int LIFETIME = -1;

	private final BossHitTrackerPlugin plugin;
	private final JComboBox<String> bossSelect = new JComboBox<>();
	private final JComboBox<String> killSelect = new JComboBox<>();
	private final JPanel content = new JPanel();
	private boolean updatingCombos;

	/** Index into the boss's recent kills (0 = newest), or LIFETIME. */
	private int selectedKill = 0;
	/** Kill count when the panel was last drawn, to notice new kills. */
	private int lastKillCount = -1;
	private String lastBoss;

	BossHitTrackerPanel(BossHitTrackerPlugin plugin)
	{
		this.plugin = plugin;

		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Boss Hit Tracker");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		header.add(title);
		header.add(Box.createVerticalStrut(6));

		header.add(fieldLabel("Boss"));
		bossSelect.setAlignmentX(LEFT_ALIGNMENT);
		header.add(bossSelect);
		header.add(Box.createVerticalStrut(6));

		header.add(fieldLabel("Kill"));
		killSelect.setAlignmentX(LEFT_ALIGNMENT);
		killSelect.setToolTipText("Show one kill, or all kills combined");
		header.add(killSelect);
		header.add(Box.createVerticalStrut(6));

		JPanel buttons = new JPanel(new GridLayout(1, 2, 6, 0));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		buttons.setAlignmentX(LEFT_ALIGNMENT);
		JButton copy = new JButton("Copy CSV");
		copy.setToolTipText("Copy all bosses and weapons to the clipboard as CSV (paste into a spreadsheet)");
		copy.addActionListener(e -> Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new StringSelection(plugin.exportCsv()), null));
		JButton reset = new JButton("Reset boss");
		reset.setToolTipText("Delete all tracked hits for the selected boss");
		reset.addActionListener(e -> confirmReset());
		buttons.add(copy);
		buttons.add(reset);
		header.add(buttons);

		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);

		// Stop BoxLayout from stretching these vertically
		for (javax.swing.JComponent c : new javax.swing.JComponent[]{bossSelect, killSelect, buttons})
		{
			c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getPreferredSize().height));
		}

		add(header, BorderLayout.NORTH);
		add(content, BorderLayout.CENTER);

		bossSelect.addActionListener(e ->
		{
			if (!updatingCombos)
			{
				selectedKill = 0;
				showSelectedBoss();
			}
		});
		killSelect.addActionListener(e ->
		{
			if (!updatingCombos)
			{
				int index = killSelect.getSelectedIndex();
				selectedKill = index <= 0 ? LIFETIME : index - 1;
				showSelectedBoss();
			}
		});

		rebuild();
	}

	/** Reload the boss list and redraw. Call on the Swing thread. */
	void rebuild()
	{
		String selected = (String) bossSelect.getSelectedItem();
		List<String> names = plugin.getBossNames();

		updatingCombos = true;
		bossSelect.removeAllItems();
		for (String name : names)
		{
			bossSelect.addItem(name);
		}
		if (selected != null && names.contains(selected))
		{
			bossSelect.setSelectedItem(selected);
		}
		updatingCombos = false;

		showSelectedBoss();
	}

	private void showSelectedBoss()
	{
		content.removeAll();
		String boss = (String) bossSelect.getSelectedItem();
		BossStats stats = boss == null ? null : plugin.getBossStats(boss);

		if (stats == null)
		{
			updatingCombos = true;
			killSelect.removeAllItems();
			updatingCombos = false;
			content.add(textLine("No kills tracked yet. Kill a boss and your hits will show up here.", ColorScheme.LIGHT_GRAY_COLOR));
			finishContent();
			return;
		}

		List<KillRecord> kills = stats.getRecentKills();

		// When a new kill comes in, keep showing the newest kill if that's what you were looking at;
		// otherwise shift the selection so it stays on the same kill.
		if (boss.equals(lastBoss) && lastKillCount >= 0 && stats.getKills() > lastKillCount && selectedKill > 0)
		{
			selectedKill += stats.getKills() - lastKillCount;
		}
		if (selectedKill >= kills.size())
		{
			selectedKill = kills.isEmpty() ? LIFETIME : kills.size() - 1;
		}
		lastBoss = boss;
		lastKillCount = stats.getKills();

		fillKillSelect(stats, kills);

		if (selectedKill == LIFETIME)
		{
			showLifetime(stats);
		}
		else
		{
			showKill(kills.get(selectedKill), stats.getKills() - selectedKill);
		}

		content.add(Box.createVerticalStrut(6));
		content.add(sectionTitle("Recent kills"));
		for (int i = 0; i < kills.size(); i++)
		{
			content.add(killRow(stats, kills.get(i), i));
		}
		if (!kills.isEmpty())
		{
			content.add(textLine("Click a kill to see its weapons.", ColorScheme.MEDIUM_GRAY_COLOR));
		}

		finishContent();
	}

	private void fillKillSelect(BossStats stats, List<KillRecord> kills)
	{
		updatingCombos = true;
		killSelect.removeAllItems();
		killSelect.addItem(ALL_KILLS);
		for (int i = 0; i < kills.size(); i++)
		{
			KillRecord k = kills.get(i);
			String label = "Kill #" + (stats.getKills() - i) + "  (" + duration(k) + ")";
			if (i == 0)
			{
				label += "  (latest)";
			}
			killSelect.addItem(label);
		}
		killSelect.setSelectedIndex(selectedKill == LIFETIME ? 0 : selectedKill + 1);
		updatingCombos = false;
	}

	private void showLifetime(BossStats stats)
	{
		long totalDamage = 0;
		int totalHits = 0;
		for (WeaponStats w : stats.getWeapons().values())
		{
			totalDamage += w.getDamage();
			totalHits += w.getHits();
		}

		content.add(sectionTitle("All kills"));
		content.add(textLine("Kills: " + NUMBER.format(stats.getKills()), Color.WHITE));
		content.add(textLine("Hits: " + NUMBER.format(totalHits) + "   Damage: " + NUMBER.format(totalDamage), Color.WHITE));
		if (stats.getKills() > 0)
		{
			content.add(textLine("Avg damage per kill: " + NUMBER.format(totalDamage / stats.getKills()), Color.WHITE));
		}
		content.add(Box.createVerticalStrut(6));

		content.add(sectionTitle("By weapon (all kills)"));
		addWeaponCards(stats.getWeapons(), totalDamage);
	}

	private void showKill(KillRecord kill, int killNumber)
	{
		SimpleDateFormat date = new SimpleDateFormat("MMM d, yyyy h:mm a");
		content.add(sectionTitle("Kill #" + killNumber));
		content.add(textLine(date.format(new Date(kill.getTimestamp())) + "   Time: " + duration(kill), Color.WHITE));
		content.add(textLine("Hits: " + NUMBER.format(kill.getTotalHits()) + "   Damage: " + NUMBER.format(kill.getTotalDamage()), Color.WHITE));
		content.add(Box.createVerticalStrut(6));

		content.add(sectionTitle(kill.hasOtherPlayers() ? "Your weapons (this kill)" : "By weapon (this kill)"));
		addWeaponCards(kill.getWeapons(), kill.getTotalDamage());

		if (kill.hasOtherPlayers())
		{
			content.add(Box.createVerticalStrut(6));
			content.add(sectionTitle("Party (this kill)"));
			long everyone = kill.getEveryoneDamage();
			List<Map.Entry<String, Map<String, WeaponStats>>> players = new ArrayList<>(kill.getPlayers().entrySet());
			players.sort((a, b) -> Long.compare(KillRecord.totalDamage(b.getValue()), KillRecord.totalDamage(a.getValue())));
			for (Map.Entry<String, Map<String, WeaponStats>> e : players)
			{
				content.add(playerCard(e.getKey(), e.getValue(), everyone));
				content.add(Box.createVerticalStrut(4));
			}
		}
	}

	/** One player's damage in a kill, with a line per weapon. */
	private JPanel playerCard(String player, Map<String, WeaponStats> weapons, long everyoneDamage)
	{
		JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(5, 7, 5, 7));
		card.setAlignmentX(LEFT_ALIGNMENT);

		long damage = KillRecord.totalDamage(weapons);
		double share = everyoneDamage == 0 ? 0 : 100.0 * damage / everyoneDamage;
		boolean unshared = KillRecord.OTHER_PLAYERS.equals(player);

		JLabel name = new JLabel(player);
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(unshared ? ColorScheme.LIGHT_GRAY_COLOR : ColorScheme.BRAND_ORANGE);
		card.add(leftAligned(name));
		card.add(leftAligned(small(String.format("Dmg %s (%.0f%%)  ·  Hits %s", NUMBER.format(damage), share,
			NUMBER.format(KillRecord.totalHits(weapons))))));

		if (unshared)
		{
			card.add(leftAligned(small("Not sharing their hits")));
			return fullWidth(card);
		}

		List<Map.Entry<String, WeaponStats>> sorted = new ArrayList<>(weapons.entrySet());
		sorted.sort((a, b) -> Long.compare(b.getValue().getDamage(), a.getValue().getDamage()));
		for (Map.Entry<String, WeaponStats> e : sorted)
		{
			WeaponStats w = e.getValue();
			JLabel line = small(String.format("<html>%s<br>&nbsp;&nbsp;%s dmg · %d hits · max %d</html>",
				e.getKey(), NUMBER.format(w.getDamage()), w.getHits(), w.getMaxHit()));
			line.setBorder(new EmptyBorder(3, 0, 0, 0));
			card.add(leftAligned(line));
		}
		return fullWidth(card);
	}

	private void addWeaponCards(Map<String, WeaponStats> weaponMap, long totalDamage)
	{
		List<Map.Entry<String, WeaponStats>> weapons = new ArrayList<>(weaponMap.entrySet());
		weapons.sort((a, b) -> Long.compare(b.getValue().getDamage(), a.getValue().getDamage()));
		for (Map.Entry<String, WeaponStats> e : weapons)
		{
			content.add(weaponCard(e.getKey(), e.getValue(), totalDamage));
			content.add(Box.createVerticalStrut(4));
		}
	}

	private JPanel weaponCard(String weapon, WeaponStats w, long totalDamage)
	{
		JPanel card = new JPanel(new GridLayout(0, 1, 0, 1));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(5, 7, 5, 7));
		card.setAlignmentX(LEFT_ALIGNMENT);

		JLabel name = new JLabel(weapon);
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(ColorScheme.BRAND_ORANGE);
		card.add(name);

		double share = totalDamage == 0 ? 0 : 100.0 * w.getDamage() / totalDamage;
		card.add(small(String.format("Hits %s  ·  Dmg %s (%.0f%%)", NUMBER.format(w.getHits()), NUMBER.format(w.getDamage()), share)));
		card.add(small(String.format("Avg %.1f  ·  Max %d", w.getAverageHit(), w.getMaxHit())));
		card.add(small(String.format("Zeros %s  ·  Landed %.0f%%", NUMBER.format(w.getZeros()), w.getNonZeroPercent())));
		return card;
	}

	private JLabel killRow(BossStats stats, KillRecord k, int index)
	{
		boolean selected = index == selectedKill;
		JLabel row = textLine(String.format("#%d  %s  %s dmg  %d hits%s",
			stats.getKills() - index, duration(k), NUMBER.format(k.getTotalDamage()), k.getTotalHits(),
			k.hasOtherPlayers() ? "  (party)" : ""),
			selected ? ColorScheme.BRAND_ORANGE : ColorScheme.LIGHT_GRAY_COLOR);
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				selectedKill = index;
				showSelectedBoss();
			}
		});
		return row;
	}

	private void finishContent()
	{
		content.revalidate();
		content.repaint();
	}

	private static String duration(KillRecord k)
	{
		long secs = k.getDurationMs() / 1000;
		return String.format("%d:%02d", secs / 60, secs % 60);
	}

	private void confirmReset()
	{
		String boss = (String) bossSelect.getSelectedItem();
		if (boss == null)
		{
			return;
		}
		int choice = JOptionPane.showConfirmDialog(this,
			"Delete all tracked hits for " + boss + "?", "Reset boss", JOptionPane.YES_NO_OPTION);
		if (choice == JOptionPane.YES_OPTION)
		{
			plugin.resetBoss(boss);
		}
	}

	private static JPanel fullWidth(JPanel panel)
	{
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		return panel;
	}

	private static JLabel leftAligned(JLabel label)
	{
		label.setAlignmentX(LEFT_ALIGNMENT);
		return label;
	}

	private static JLabel fieldLabel(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel sectionTitle(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(Color.WHITE);
		l.setBorder(new EmptyBorder(0, 0, 3, 0));
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel textLine(String text, Color color)
	{
		JLabel l = new JLabel("<html>" + text + "</html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		l.setAlignmentX(LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel small(String text)
	{
		JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.TEXT_COLOR);
		return l;
	}
}

